mod jardin {              // un module nommé `jardin`
    mod legumes {         // un module imbriqué dans `jardin`
        fn planter() {
            println!("On plante une carotte");
        }
    }
}

fn main() {
    // On verra juste après comment appeler `planter` depuis ici.
}

mod jardin {
    pub mod legumes {          // module rendu public
        pub fn planter() {     // fonction rendue publique
            println!("On plante une carotte");
        }
    }
}

fn main() {
    // `crate` désigne la racine du paquet courant.
    crate::jardin::legumes::planter();
}

mod cuisine {
    pub fn servir() {
        preparer();          // chemin implicite : même module
        self::preparer();    // identique, mais explicite avec `self`
    }

    fn preparer() {
        println!("On prépare le plat");
    }

    pub mod salle {
        pub fn annoncer() {
            super::servir();  // `super` remonte au module `cuisine`
        }
    }
}

fn main() {
    cuisine::salle::annoncer();
}

mod jardin {
    pub mod legumes {
        pub fn planter() {
            println!("On plante une carotte");
        }
    }
}

use crate::jardin::legumes;   // raccourci vers le module `legumes`

fn main() {
    legumes::planter();        // plus court et on voit d'où vient `planter`
}

use rand::Rng;   // importe le trait `Rng` fourni par la crate `rand`

fn main() {
    let mut generateur = rand::thread_rng();
    // tire un entier entre 1 et 6 inclus (comme un dé)
    let de: u8 = generateur.gen_range(1..=6);
    println!("Le dé affiche : {de}");
}
